import {
  RuntimeError,
  emptyRuntimePlan,
  type RuntimeCapabilityUsage,
  type RuntimeExecutionRequest,
  type RuntimeNamespaceRequirement,
  type RuntimePlan,
  type TrustedExecutionContext,
} from '@hrbr/runtime-core'
import {
  planRuntimeNamespaceUsage,
  type RuntimeNamespaceUsagePlan,
  type SourceBindingAvailability,
} from './namespace-plan'

const SOURCE_BINDINGS_FEATURE = 'sourceBindings'

export interface RuntimePlannerOptions {
  readonly sourceBindings?: ReadonlyArray<SourceBindingAvailability> | undefined
  readonly generatedTypeBlocks?: ReadonlyArray<string> | undefined
}

export interface RuntimePlanProjection {
  readonly namespaceUsage: RuntimeNamespaceUsagePlan
  readonly runtimePlan: RuntimePlan
}

export function runtimePlannerOptionsFromRequest(
  request: RuntimeExecutionRequest
): RuntimePlannerOptions {
  const features = request.features ?? {}
  return {
    sourceBindings: decodeSourceBindings(features[SOURCE_BINDINGS_FEATURE]),
    generatedTypeBlocks: decodeStringArray(features.generatedTypeBlocks),
  }
}

export function projectRuntimeNamespaceUsage(
  usage: RuntimeNamespaceUsagePlan,
  request: RuntimeExecutionRequest,
  options: RuntimePlannerOptions = {}
): RuntimePlanProjection {
  const aliasMap = Object.fromEntries(
    [...usage.aliases.entries()].flatMap(([namespace, aliases]) =>
      aliases.map((alias) => [alias, namespace] as const)
    )
  )
  const requiredNamespaces: RuntimeNamespaceRequirement[] = usage.loadNamespaces.map(
    (namespace) => ({
      namespace,
      bindingKind: 'tool',
    })
  )
  const capabilities: RuntimeCapabilityUsage[] = [
    ...usage.loadNamespaces.map((namespace) => ({
      kind: 'tool' as const,
      key: namespace,
      metadata: { namespace },
    })),
  ]
  if (usage.orbit) capabilities.push({ kind: 'orbit', key: 'orbit' })
  if (usage.secrets) capabilities.push({ kind: 'secret', key: 'secrets' })
  if (usage.jobs) capabilities.push({ kind: 'job', key: 'jobs' })
  if (usage.step) capabilities.push({ kind: 'workflow_step', key: 'step' })

  const runtimePlan = emptyRuntimePlan({
    requiredNamespaces,
    aliasMap,
    capabilities,
    mountedInputs: request.executionInputs ?? [],
    generatedTypeBlocks: [...(options.generatedTypeBlocks ?? [])],
  })

  return { namespaceUsage: usage, runtimePlan }
}

export function createRuntimePlan(
  request: RuntimeExecutionRequest,
  _context: TrustedExecutionContext,
  options: RuntimePlannerOptions = {}
): RuntimePlan {
  return createRuntimePlanProjection(request, options).runtimePlan
}

export function createRuntimePlanProjection(
  request: RuntimeExecutionRequest,
  options: RuntimePlannerOptions = {}
): RuntimePlanProjection {
  return projectRuntimeNamespaceUsage(
    planRuntimeNamespaceUsage(request.code, options.sourceBindings ?? []),
    request,
    options
  )
}

function decodeSourceBindings(value: unknown): SourceBindingAvailability[] | undefined {
  if (value === undefined) return undefined
  if (!Array.isArray(value)) {
    throw new RuntimeError(
      'validation',
      'runtime planner sourceBindings feature must be an array',
      {
        feature: SOURCE_BINDINGS_FEATURE,
      }
    )
  }
  return value.map((item, index): SourceBindingAvailability => {
    if (typeof item !== 'object' || item === null) {
      throw new RuntimeError('validation', 'runtime planner source binding must be an object', {
        index,
      })
    }
    const record = item as Record<string, unknown>
    const kind = record.kind
    if (kind !== 'mcp' && kind !== 'api' && kind !== 'cli') {
      throw new RuntimeError('validation', 'runtime planner source binding kind is invalid', {
        index,
        kind,
      })
    }
    if (typeof record.namespace !== 'string' || record.namespace.length === 0) {
      throw new RuntimeError('validation', 'runtime planner source binding namespace is invalid', {
        index,
      })
    }
    return {
      namespace: record.namespace,
      kind,
      has_cli_bindings: record.has_cli_bindings === true,
    }
  })
}

function decodeStringArray(value: unknown): string[] | undefined {
  if (value === undefined) return undefined
  if (!Array.isArray(value) || !value.every((item) => typeof item === 'string')) {
    throw new RuntimeError(
      'validation',
      'runtime planner generatedTypeBlocks feature must be a string array'
    )
  }
  return [...value]
}
